The rule: **For each color that appears at multiple column positions (>=2), in rows where it spans multiple columns, any other color appearing in the same row range transforms to match the "spans" color.**

```python
def transform(grid):
    from collections import defaultdict

    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find colors that span multiple columns (form a "span" pattern)
    color_spans = defaultdict(lambda: {'cols': set(), 'rows': set()})

    for r in range(rows):
        cell_start = 0
        while cell_start < cols:
            if grid[r][cell_start] != 0:  # Not background
                color = grid[r][cell_start]
                cell_end = cell_start
                while cell_end < cols and grid[r][cell_end] == color:
                    cell_end += 1
                for c in range(cell_start, cell_end):
                    color_spans[color]['cols'].add(c)
                    color_spans[color]['rows'].add(r)
                cell_start = cell_end
            else:
                cell_start += 1

    # Find final positions for each color
    color_final = {c: {'cols': [], 'rows': []} for c in color_spans}
    for color, sp in color_spans.items():
        color_final[color]['cols'] = list(sp['cols'])
        color_final[color]['rows'] = list(sp['rows'])

    # Transform: other colors in same row range transform to "span" color
    for span_color in color_spans:
        span_rows = set(color_spans[span_color]['rows'])

        for other_color in color_spans:
            if other_color == span_color or other_color == 0:
                continue
            other_rows = set(color_spans[other_color]['rows'])

            common = span_rows & other_rows
            if common:
                for r in common:
                    for c in range(cols):
                        if grid[r][c] == other_color and (c not in color_spans[span_color]['cols']):
                            result[r][c] = span_color

    return result

