    Task: Find a vertical complete line (a color in a column forming >3 consecutive cells),
    then transform any horizontal color segment spanning the same row range to that color.
    """
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find background
    from collections import Counter
    counts = Counter()
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] += 1
    bg = max(counts, key=counts.get)

    # Find all vertical segments (consecutive cells in same column, same color, no bg in between)
    vertical_segments = []
    for c in range(cols):
        r, end = 0, 0
        while r < rows:
            if grid[r][c] == grid[r+1][c] and grid[r][c] != bg:
                # Found start of potential vertical segment
                start = r
                while r < rows and grid[r][c] == grid[start][c] and grid[r][c] != bg:
                    r += 1
                if r - start > 2:  # Complete vertical segment (at least 3 cells)
                    vertical_segments.append({
                        'color': grid[start][c],
                        'col': start,
                        'rows': list(range(start, r-1))
                    })
            else:
                r += 1

    # For each row, find horizontal segments of non-bg colors
    horizontal_segments = []
    for r in range(rows):
        c = 0
        while c < cols:
            if grid[r][c] != bg:
                start = c
                color = grid[r][c]
                end = c
                while end < cols and grid[r][end] == color and grid[r][end] != bg:
                    end += 1
                if end - start > 0:  # Has width
                    horizontal_segments.append({
                        'color': color,
                        'row': r,
                        'cols': list(range(start, end-1))
                    })
            c = end if end > start else c + 1

    # Transform: if horizontal segment's row range overlaps with a vertical segment's rows,
    # transform those cells to the vertical segment's color
    for h_seg in horizontal_segments:
        for v_seg in vertical_segments:
            if h_seg['row'] in v_seg['rows']:
                for c in h_seg['cols']:
                    result[h_seg['row']][c] = v_seg['color']

    return result

